<dialog id="order-update-confirmation" aria-labelledby="order-update-confirmation-title" class="m-auto w-[calc(100%-32px)] max-w-[480px] rounded-2xl border border-gray-mid bg-white p-24 text-left shadow-xl backdrop:bg-black/40">
    <h2 id="order-update-confirmation-title" class="text-18 font-semibold">Conferma aggiornamento</h2>
    <p data-order-confirm-message class="mt-16 text-13 leading-relaxed"></p>
    <label class="mt-20 flex cursor-pointer items-start gap-10 rounded-xl border border-gray-mid p-16 text-13"><input type="checkbox" data-order-confirm-notify class="mt-2 cursor-pointer rounded border-gray-mid text-bullstar focus:ring-bullstar"><span>Invia comunicazione al cliente</span></label>
    <p data-order-confirm-help class="mt-12 text-12 leading-relaxed text-gray"></p>
    <div class="mt-24 flex flex-wrap justify-end gap-12"><button type="button" data-order-confirm-cancel class="catalog-button catalog-button-secondary">Torna indietro</button><button type="button" data-order-confirm-submit class="catalog-button catalog-button-primary">Conferma aggiornamento</button></div>
</dialog>
